use std::fmt::Display;

fn show_twice<T: Display>(value: T) {
    println!("{value} {value}");
}

fn main() {
    show_twice(7);
    show_twice("hello");
    show_twice(2.5);
}

use std::fmt::Display;

fn print_larger<T: PartialOrd + Display>(a: T, b: T) {
    if a > b {
        println!("{a} is larger than {b}");
    } else {
        println!("{b} is at least as large as {a}");
    }
}

fn main() {
    print_larger(3, 9);
    print_larger("pear", "apple");
}

use std::fmt::{Debug, Display};

fn report<T, U>(label: T, data: U) -> String
where
    T: Display,
    U: Debug + Clone,
{
    let copy = data.clone();
    format!("{label}: {:?}", copy)
}

fn main() {
    println!("{}", report("scores", vec![90, 85]));
}

trait Speak {
    fn speak(&self) -> String;
}

struct Dog;

impl Speak for Dog {
    fn speak(&self) -> String {
        String::from("woof")
    }
}

fn announce(item: &impl Speak) {
    println!("it says {}", item.speak());
}

fn make_pet() -> impl Speak {
    Dog
}

fn main() {
    let pet = make_pet();
    announce(&pet);
}

#[derive(Debug, Clone, Copy, PartialEq, Default)]
struct Point {
    x: i32,
    y: i32,
}

fn main() {
    let a = Point { x: 1, y: 2 };
    let b = a;   // Copy: a is still usable
    println!("{:?} {:?} equal: {}", a, b, a == b);
    let origin = Point::default();
    println!("{:?} equal: {}", origin, a == origin);
}

